     4→ * Utility object for group code generation, validation, and formatting.
     5→ * Extracted for testability without Android dependencies.
     6→ */
     7→object GroupCodeUtils {
     8→
     9→    // Group code characters (easy to read, no ambiguous chars like 0/O, 1/I/L)
    10→    const val CODE_CHARS = "ABCDEFGHJKMNPQRSTUVWXYZ23456789"
    11→    const val CODE_LENGTH = 6
    12→
    13→    /**
    14→     * Generate a new shareable group code.
    15→     * Returns raw 6-character code (e.g., "RIDE4K", "TEAM7X").
    16→     * Use formatGroupCode() for display (e.g., "RIDE-4K").
    17→     */
    18→    fun generateGroupCode(): String {
    19→        return buildString {
    20→            repeat(CODE_LENGTH) {
    21→                append(CODE_CHARS.random())
    22→            }
    23→        }
    24→    }
    25→
    26→    /**
    27→     * Validate a group code format.
    28→     */
    29→    fun isValidGroupCode(code: String): Boolean {
    30→        val normalized = normalizeGroupCode(code)
    31→        if (normalized.length != CODE_LENGTH) return false
    32→        return normalized.all { it in CODE_CHARS }
    33→    }
    34→
    35→    /**
    36→     * Normalize a group code (remove dashes, spaces, uppercase).
    37→     */
    38→    fun normalizeGroupCode(code: String): String {
    39→        return code.uppercase().replace("-", "").replace(" ", "")
    40→    }
    41→
    42→    /**
    43→     * Format a group code for display (XXXX-XX format).
    44→     */
    45→    fun formatGroupCode(code: String): String {
    46→        val normalized = normalizeGroupCode(code)
    47→        return if (normalized.length >= 4) {
    48→            "${normalized.substring(0, 4)}-${normalized.substring(4)}"
    49→        } else {
    50→            normalized
    51→        }
    52→    }
    53→}
